     1	'use strict';
     2	
     3	const crypto = require('node:crypto');
     4	const { invalid, conflict } = require('../lib/errors');
     5	
     6	const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
     7	const MIN_PASSWORD_LENGTH = 8;
     8	
     9	function hashPassword(password, salt) {
    10	  return crypto.scryptSync(password, salt, 32).toString('hex');
    11	}
    12	
    13	function normalizeEmail(email) {
    14	  return typeof email === 'string' ? email.trim().toLowerCase() : '';
    15	}
    16	
    17	function toPublic(user) {
    18	  return { id: user.id, email: user.email, name: user.name, role: user.role, createdAt: user.createdAt };
    19	}
    20	
    21	function createUserService({ store }) {
    22	  function register({ email, password, name }, role = 'customer') {
    23	    const normalized = normalizeEmail(email);
    24	    if (!EMAIL_PATTERN.test(normalized)) throw invalid('a valid email is required');
    25	    if (typeof password !== 'string' || password.length < MIN_PASSWORD_LENGTH) {
    26	      throw invalid(`password must be at least ${MIN_PASSWORD_LENGTH} characters`);
    27	    }
    28	    if (typeof name !== 'string' || name.trim() === '') throw invalid('name is required');
    29	    if (store.findOne('users', (user) => user.email === normalized)) throw conflict('email already registered');
    30	    const salt = crypto.randomBytes(16).toString('hex');
    31	    return toPublic(store.insert('users', {
    32	      email: normalized,
    33	      name: name.trim(),
    34	      role,
    35	      salt,
    36	      passwordHash: hashPassword(password, salt),
    37	      createdAt: new Date().toISOString(),
    38	    }));
    39	  }
    40	
    41	  function verifyCredentials(email, password) {
    42	    if (typeof password !== 'string') return null;
    43	    const normalized = normalizeEmail(email);
    44	    const user = store.findOne('users', (candidate) => candidate.email === normalized);
    45	    if (!user) return null;
    46	    const expected = Buffer.from(user.passwordHash, 'hex');
    47	    const actual = Buffer.from(hashPassword(password, user.salt), 'hex');
    48	    return crypto.timingSafeEqual(expected, actual) ? toPublic(user) : null;
    49	  }
    50	
    51	  function find(id) {
    52	    const user = store.get('users', id);
    53	    return user ? toPublic(user) : null;
    54	  }
    55	
    56	  return { register, verifyCredentials, find, toPublic };
    57	}
    58	
    59	module.exports = { createUserService };
