===== src/orders/service.js =====
     1	'use strict';
     2	
     3	const { invalid, notFound, conflict } = require('../lib/errors');
     4	const { isAmount, sumLines } = require('../lib/money');
     5	const { paginate } = require('../lib/pagination');
     6	
     7	const TRANSITIONS = {
     8	  pending: ['paid', 'cancelled'],
     9	  paid: ['shipped', 'cancelled'],
    10	  shipped: ['delivered', 'cancelled'],
    11	  delivered: [],
    12	  cancelled: [],
    13	};
    14	
    15	function normalizeItems(items) {
    16	  if (!Array.isArray(items) || items.length === 0) throw invalid('an order needs at least one item');
    17	  return items.map((item) => {
    18	    if (!item || typeof item.sku !== 'string' || item.sku.trim() === '') throw invalid('every item needs a sku');
    19	    if (!isAmount(item.unitPrice)) throw invalid('unitPrice must be a positive amount with at most two decimals');
    20	    if (!Number.isInteger(item.quantity) || item.quantity < 1) throw invalid('quantity must be a positive integer');
    21	    return { sku: item.sku.trim(), unitPrice: item.unitPrice, quantity: item.quantity };
    22	  });
    23	}
    24	
    25	function createOrderService({ store }) {
    26	  function create(user, { items }) {
    27	    const lines = normalizeItems(items);
    28	    return store.insert('orders', {
    29	      userId: user.id,
    30	      items: lines,
    31	      total: sumLines(lines),
    32	      status: 'pending',
    33	      createdAt: new Date().toISOString(),
    34	    });
    35	  }
    36	
    37	  function get(id) {
    38	    const order = store.get('orders', id);
    39	    if (!order) throw notFound('order not found');
    40	    return order;
    41	  }
    42	
    43	  function getOwned(user, id) {
    44	    const order = get(id);
    45	    if (user.role !== 'admin' && order.userId !== user.id) throw notFound('order not found');
    46	    return order;
    47	  }
    48	
    49	  function list(user, query) {
    50	    const visible = store.list('orders', (order) => user.role === 'admin' || order.userId === user.id);
    51	    return paginate(visible, query);
    52	  }
    53	
    54	  function all() {
    55	    return store.list('orders');
    56	  }
    57	
    58	  function transition(order, next, patch = {}) {
    59	    if (!TRANSITIONS[order.status].includes(next)) {
    60	      throw conflict(`order cannot move from ${order.status} to ${next}`);
    61	    }
    62	    return store.update('orders', order.id, { ...patch, status: next, updatedAt: new Date().toISOString() });
    63	  }
    64	
    65	  return {
    66	    create,
    67	    get,
    68	    getOwned,
    69	    list,
    70	    all,
    71	    cancel: (user, id) => transition(getOwned(user, id), 'cancelled'),
    72	    ship: (id) => transition(get(id), 'shipped'),
    73	    deliver: (id) => transition(get(id), 'delivered'),
    74	    markPaid: (id, paymentId) => transition(get(id), 'paid', { paymentId }),
    75	  };
    76	}
    77	
    78	module.exports = { createOrderService };
===== src/app.js =====
     1	'use strict';
     2	
     3	const http = require('node:http');
     4	const path = require('node:path');
     5	const { createRouter } = require('./http/router');
     6	const { createStore } = require('./store/memoryStore');
     7	const { createTokenService } = require('./auth/tokens');
     8	const { createGuard } = require('./auth/guard');
     9	const { createUserService } = require('./users/service');
    10	const { createOrderService } = require('./orders/service');
    11	const { createPaymentService } = require('./payments/service');
    12	const { registerUserRoutes } = require('./users/routes');
    13	const { registerOrderRoutes } = require('./orders/routes');
    14	const { registerPaymentRoutes } = require('./payments/routes');
    15	const { registerReportRoutes } = require('./reports/routes');
    16	
    17	function createApp(options = {}) {
    18	  const store = createStore();
    19	  const tokens = createTokenService({ secret: options.secret, ttlSeconds: options.tokenTtlSeconds ?? 3600 });
    20	  const users = createUserService({ store });
    21	  const orders = createOrderService({ store });
    22	  const payments = createPaymentService({ store, orders, provider: options.paymentProvider });
    23	  const guard = createGuard({ tokens, users });
    24	
    25	  const router = createRouter();
    26	  registerUserRoutes(router, { users, tokens, guard, store });
    27	  registerOrderRoutes(router, { orders, guard });
    28	  registerPaymentRoutes(router, { payments, guard });
    29	  registerReportRoutes(router, { orders, guard, reportDir: options.reportDir || path.resolve('reports') });
    30	
    31	  if (options.admin) users.register(options.admin, 'admin');
    32	
    33	  const server = http.createServer((req, res) => router.handle(req, res));
    34	  return {
    35	    listen(port = 0, host = '127.0.0.1') {
    36	      return new Promise((resolve) => server.listen(port, host, () => resolve(server.address().port)));
    37	    },
    38	    close() {
    39	      return new Promise((resolve) => server.close(() => resolve()));
    40	    },
    41	  };
    42	}
    43	
    44	if (require.main === module) {
    45	  const app = createApp({
    46	    secret: process.env.APP_SECRET,
    47	    reportDir: process.env.REPORT_DIR,
    48	    admin: process.env.ADMIN_EMAIL
    49	      ? { email: process.env.ADMIN_EMAIL, password: <redacted>, name: 'Administrator' }
    50	      : undefined,
    51	  });
    52	  app.listen(Number(process.env.PORT) || 3000, '0.0.0.0').then((port) => {
    53	    process.stdout.write(`orders-service listening on ${port}\n`);
    54	  });
    55	}
    56	
    57	module.exports = { createApp };
===== src/http/router.js =====
     1	'use strict';
     2	
     3	const { AppError, notFound } = require('../lib/errors');
     4	const { sendJson, sendText, readJson } = require('./respond');
     5	
     6	const STATUS_BY_CODE = {
     7	  invalid: 400,
     8	  unauthorized: 401,
     9	  forbidden: 403,
    10	  not_found: 404,
    11	  conflict: 409,
    12	};
    13	
    14	const BODY_METHODS = new Set(['POST', 'PUT', 'PATCH']);
    15	
    16	function matchPath(parts, segments) {
    17	  if (parts.length !== segments.length) return null;
    18	  const params = {};
    19	  for (let i = 0; i < parts.length; i += 1) {
    20	    if (parts[i].startsWith(':')) {
    21	      params[parts[i].slice(1)] = decodeURIComponent(segments[i]);
    22	    } else if (parts[i] !== segments[i]) {
    23	      return null;
    24	    }
    25	  }
    26	  return params;
    27	}
    28	
    29	function createRouter() {
    30	  const routes = [];
    31	
    32	  function add(method, pattern, handler) {
    33	    routes.push({ method, parts: pattern.split('/').filter(Boolean), handler });
    34	  }
    35	
    36	  async function dispatch(req, res) {
    37	    const url = new URL(req.url, 'http://localhost');
    38	    const segments = url.pathname.split('/').filter(Boolean);
    39	    let pathMatched = false;
    40	    for (const route of routes) {
    41	      const params = matchPath(route.parts, segments);
    42	      if (!params) continue;
    43	      pathMatched = true;
    44	      if (route.method !== req.method) continue;
    45	      const body = BODY_METHODS.has(req.method) ? await readJson(req) : {};
    46	      const query = Object.fromEntries(url.searchParams);
    47	      const result = await route.handler({ req, params, query, body });
    48	      if (result.text !== undefined) return sendText(res, result.status, result.text, result.contentType);
    49	      return sendJson(res, result.status, result.body);
    50	    }
    51	    if (pathMatched) return sendJson(res, 405, { error: 'method not allowed' });
    52	    throw notFound('route not found');
    53	  }
    54	
    55	  async function handle(req, res) {
    56	    try {
    57	      await dispatch(req, res);
    58	    } catch (error) {
    59	      if (error instanceof URIError) return sendJson(res, 400, { error: 'malformed path' });
    60	      if (error instanceof AppError) return sendJson(res, STATUS_BY_CODE[error.code] || 400, { error: error.message });
    61	      return sendJson(res, 500, { error: 'internal error' });
    62	    }
    63	  }
    64	
    65	  return { add, handle };
    66	}
    67	
    68	module.exports = { createRouter };
===== src/store/memoryStore.js =====
     1	'use strict';
     2	
     3	const crypto = require('node:crypto');
     4	
     5	function createStore() {
     6	  const collections = new Map();
     7	
     8	  function collection(name) {
     9	    if (!collections.has(name)) collections.set(name, new Map());
    10	    return collections.get(name);
    11	  }
    12	
    13	  return {
    14	    insert(name, doc) {
    15	      const record = { ...doc, id: crypto.randomUUID() };
    16	      collection(name).set(record.id, record);
    17	      return structuredClone(record);
    18	    },
    19	    get(name, id) {
    20	      const record = collection(name).get(id);
    21	      return record ? structuredClone(record) : null;
    22	    },
    23	    update(name, id, patch) {
    24	      const record = collection(name).get(id);
    25	      if (!record) return null;
    26	      Object.assign(record, patch);
    27	      return structuredClone(record);
    28	    },
    29	    list(name, predicate = () => true) {
    30	      return [...collection(name).values()].filter(predicate).map((record) => structuredClone(record));
    31	    },
    32	    findOne(name, predicate) {
    33	      for (const record of collection(name).values()) {
    34	        if (predicate(record)) return structuredClone(record);
    35	      }
    36	      return null;
    37	    },
    38	  };
    39	}
    40	
    41	module.exports = { createStore };

