const fs = require('node:fs');
const test = require('node:test');
const assert = require('node:assert/strict');
const { startApp } = require('./helpers');

const CSV_HEADER = 'id,userId,status,total,createdAt';

async function placeOrder(call, token, sku) {
  const created = await call('POST', '/orders', { token, body: { items: [{ sku, unitPrice: 8, quantity: 1 }] } });
  assert.equal(created.status, 201);
  return created.body;
}

async function exportLines(call, adminToken, body) {
  const exported = await call('POST', '/reports/orders', { token: adminToken, body });
  assert.equal(exported.status, 201);
  const download = await call('GET', `/reports/${exported.body.name}`, { token: adminToken });
  assert.equal(download.status, 200);
  return download.text.trim().split('\n');
}

function ids(lines) {
  assert.equal(lines[0], CSV_HEADER);
  return lines.slice(1).map((line) => line.split(',')[0]);
}

