test('a status filter exports only the orders in that state', async (t) => {
  const { call, signUp, adminToken } = await startApp(t);
  const alice = await signUp('alice@example.com');
  const stillPending = await placeOrder(call, alice, 'MUG-1');
  const paid = await placeOrder(call, alice, 'MUG-2');
  const payment = await call('POST', '/payments', { token: alice, body: { orderId: paid.id, amount: paid.total } });
  assert.equal(payment.status, 201);

  assert.deepEqual(ids(await exportLines(call, adminToken, { status: 'paid' })), [paid.id]);
  assert.deepEqual(ids(await exportLines(call, adminToken, { status: 'pending' })), [stillPending.id]);
});

test('every order state is an accepted filter', async (t) => {
  const { call, signUp, adminToken } = await startApp(t);
  const alice = await signUp('alice@example.com');
  const expected = {};

  expected.pending = (await placeOrder(call, alice, 'PENDING-1')).id;

  for (const status of ['paid', 'shipped', 'delivered', 'cancelled']) {
    const order = await placeOrder(call, alice, `${status.toUpperCase()}-1`);
    expected[status] = order.id;
    if (status === 'cancelled') {
      assert.equal((await call('POST', `/orders/${order.id}/cancel`, { token: alice })).status, 200);
      continue;
    }
    const payment = await call('POST', '/payments', { token: alice, body: { orderId: order.id, amount: order.total } });
    assert.equal(payment.status, 201);
    if (status === 'paid') continue;
    assert.equal((await call('POST', `/orders/${order.id}/ship`, { token: adminToken })).status, 200);
    if (status === 'shipped') continue;
    assert.equal((await call('POST', `/orders/${order.id}/deliver`, { token: adminToken })).status, 200);
  }

  for (const [status, id] of Object.entries(expected)) {
    assert.deepEqual(ids(await exportLines(call, adminToken, { status })), [id], status);
  }
});

test('a status with no matching orders exports only the header', async (t) => {
  const { call, signUp, adminToken } = await startApp(t);
  const alice = await signUp('alice@example.com');
  await placeOrder(call, alice, 'MUG-1');

  for (const status of ['paid', 'shipped', 'delivered', 'cancelled']) {
    const lines = await exportLines(call, adminToken, { status });
    assert.deepEqual(lines, [CSV_HEADER], status);
  }
});

test('an unknown status is rejected and writes no report', async (t) => {
  const { call, signUp, adminToken, reportDir } = await startApp(t);
  const alice = await signUp('alice@example.com');
  await placeOrder(call, alice, 'MUG-1');

  for (const status of ['refunded', '', 'PAID', 7, null, { status: 'paid' }]) {
    const rejected = await call('POST', '/reports/orders', { token: adminToken, body: { status } });
    assert.equal(rejected.status, 400, JSON.stringify(status));
  }
  assert.deepEqual(fs.readdirSync(reportDir), []);
});

